import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const text = (value, name, max = 20000) => {
  if (typeof value !== 'string' || !value.trim() || value.length > max)
    throw Error(name + ' must be a nonempty string ≤ ' + max + ' characters');
  return value;
};

const strings = (value, name, nonempty = true) => {
  if (!Array.isArray(value) || (nonempty && !value.length) || value.length > 50)
    throw Error(name + ' must be an array' + (nonempty ? ' with entries' : ''));
  return value.map((v) => text(v, name, 2000));
};

export function buildPacket(input) {
  text(input.goal, 'goal');
  const constraints = strings(input.constraints, 'constraints'),
    checks = strings(input.checks, 'checks');
  if (!Array.isArray(input.sources) || !input.sources.length) throw Error('sources required');
  const body = [
    '# Current goal\n' + input.goal,
    '# Constraints\n' + constraints.join('\n'),
    '# Selected sources\n' +
      input.sources
        .map(
          (s) =>
            '## ' + text(s.path, 'source path', 500) + '\n' + text(s.text, 'source body', 1000000),
        )
        .join('\n\n'),
    '# Acceptance checks\n' + checks.join('\n'),
  ].join('\n\n');
  return {
    text: body,
    bytes: Buffer.byteLength(body),
    scope: 'Complete supplied text; byte count is not native tokens.',
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const input = process.argv[2];
    if (!input || fs.statSync(input).size > 1024 * 1024)
      throw Error('Supply a bounded local JSON file');
    console.log(JSON.stringify(buildPacket(JSON.parse(fs.readFileSync(input, 'utf8'))), null, 2));
  } catch (error) {
    console.error(error instanceof SyntaxError ? 'Invalid local JSON.' : error.message);
    process.exitCode = 1;
  }
}

import { captureOutput } from './lib/bound-tool-output.mjs';
let raw = '';
try {
  for await (const chunk of process.stdin) {
    raw += chunk;
    if (raw.length > 4000000) throw Error('Hook input too large');
  }
  const event = JSON.parse(raw || '{}');
  const output = await (async () => {
    return captureOutput(event);
  })();
  process.stdout.write(typeof output === 'string' ? output : JSON.stringify(output || {}));
} catch (error) {
  process.stderr.write(
    'Context component skipped: ' +
      (error instanceof SyntaxError ? 'Invalid local JSON.' : error.message) +
      '\n',
  );
}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { checkedPath, privateDirectory, writePrivate, withStoreLock, limits } from './files.mjs';

const home = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');

function session(event) {
  if (
    typeof event.cwd !== 'string' ||
    typeof event.session_id !== 'string' ||
    !event.session_id ||
    event.session_id.length > 256
  )
    throw Error('Session identity unavailable');
  return crypto
    .createHash('sha256')
    .update(fs.realpathSync(event.cwd) + '\0' + event.session_id)
    .digest('hex');
}

export function captureOutput(event) {
  const r = event.tool_response;
  if (
    event.hook_event_name !== 'PostToolUse' ||
    event.tool_name !== 'Bash' ||
    !r ||
    typeof r.stdout !== 'string' ||
    typeof r.stderr !== 'string' ||
    r.stderr !== '' ||
    r.interrupted !== false ||
    r.isImage !== false ||
    r.error ||
    (r.exitCode !== undefined && r.exitCode !== 0) ||
    (r.exit_code !== undefined && r.exit_code !== 0) ||
    r.stdout.length <= 8000
  )
    return {};
  const body = JSON.stringify(r);
  if (Buffer.byteLength(body) > limits.artifactBytes) return {};
  const root = privateDirectory(path.join(home, 'state', 'bounded-results'), true);
  const sid = session(event),
    digest = crypto.createHash('sha256').update(body).digest('hex');
  const dest = checkedPath(path.join(root, sid + '-' + digest + '.json'));
  const stored = withStoreLock(root, () => {
    const files = fs.readdirSync(root).filter((n) => /^[a-f0-9]{64}-[a-f0-9]{64}\.json$/.test(n));
    const total = files.reduce(
      (n, name) => n + fs.statSync(checkedPath(path.join(root, name))).size,
      0,
    );
    if (
      !fs.existsSync(dest) &&
      (files.length >= limits.artifactFiles ||
        total + Buffer.byteLength(body) > limits.artifactTotal)
    )
      return null;
    if (fs.existsSync(dest)) {
      if (fs.readFileSync(dest, 'utf8') !== body) throw Error('Artifact collision');
    } else writePrivate(dest, body);
    return dest;
  });
  if (!stored) return {};
  const suffix =
    '\n[Bounded preview; full structured result: ' +
    stored +
    '. Read it when omitted facts matter.]';
  return {
    hookSpecificOutput: {
      hookEventName: 'PostToolUse',
      updatedToolOutput: { ...r, stdout: r.stdout.slice(0, 8000 - suffix.length) + suffix },
    },
  };
}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export const limits = Object.freeze({
  traceBytes: 256 * 1024,
  traceFiles: 20,
  artifactBytes: 4 * 1024 * 1024,
  artifactTotal: 16 * 1024 * 1024,
  artifactFiles: 20,
});

// Refuse redirects before opening local outputs. This is not isolation from
// malicious processes running as the same OS user, or encryption at rest.
export function checkedPath(file) {
  const target = path.resolve(file);
  let cursor = path.parse(target).root;
  for (const part of target.slice(cursor.length).split(path.sep).filter(Boolean)) {
    cursor = path.join(cursor, part);
    try {
      const st = fs.lstatSync(cursor);
      if (st.isSymbolicLink()) throw Error('Refusing symbolic-link local data target');
      if (
        cursor === target &&
        ((!st.isFile() && !st.isDirectory()) || (st.isFile() && st.nlink !== 1))
      )
        throw Error('Refusing nonregular or hardlinked local data target');
    } catch (e) {
      if (e.code !== 'ENOENT') throw e;
    }
  }
  return target;
}

export function privateDirectory(folder, owned = false) {
  const target = checkedPath(folder);
  fs.mkdirSync(target, { recursive: true, mode: 0o700 });
  if (!fs.lstatSync(target).isDirectory()) throw Error('Local data directory required');
  if (owned && process.platform !== 'win32') {
    const st = fs.statSync(target);
    if (process.getuid && st.uid !== process.getuid())
      throw Error('Local data directory owned by another user');
    fs.chmodSync(target, 0o700);
  }
  return target;
}

export function writePrivate(file, value) {
  const target = checkedPath(file);
  privateDirectory(path.dirname(target));
  if (fs.existsSync(target) && !fs.lstatSync(target).isFile())
    throw Error('Regular output file required');
  const scratch = path.join(path.dirname(target), '.write-' + crypto.randomUUID());
  let fd;
  try {
    fd = fs.openSync(scratch, 'wx', 0o600);
    fs.writeFileSync(fd, value);
    fs.closeSync(fd);
    fd = undefined;
    checkedPath(target);
    fs.renameSync(scratch, target);
  } finally {
    if (fd !== undefined) fs.closeSync(fd);
    fs.rmSync(scratch, { force: true });
  }
  return target;
}

// A short-lived lock bounds concurrent hook writes. Contention or a stale lock
// skips capture; original tool output is retained. No evidence is auto-deleted.
export function withStoreLock(root, work) {
  const lock = checkedPath(path.join(root, '.capture-lock'));
  try {
    fs.mkdirSync(lock, { mode: 0o700 });
  } catch (e) {
    if (e.code === 'EEXIST') return null;
    throw e;
  }
  try {
    return work();
  } finally {
    fs.rmdirSync(lock);
  }
}

